# generate tests/fixtures/emitc_corpus/demand_chain_deep.z and its golden: a
# chain of functions, each reached only through the body of the one before
import sys
N = 5000
src = ['''# A chain of %d functions, each called only by the next, and `main` calling
# the last. The compiler checks a function when a use reaches it, so it meets
# each one inside the body of its caller: the length of such a chain must cost
# the compiler no stack. Generated by tools/testgen/callchain.py.
f0: function {n: i64} out i64 is {
    return n
}
''' % N]
for i in range(1, N):
    src.append('\nf%d: function {n: i64} out i64 is {\n    return (f%d :n) + 1\n}\n' % (i, i - 1))
src.append('\nmain: function is {\n    print "\\{f%d n: 1}"\n}\n' % (N - 1))
open(sys.argv[1] + '/emitc_corpus/demand_chain_deep.z', 'w').write(''.join(src))
open(sys.argv[1] + '/run_golden/demand_chain_deep.out', 'w').write('%d\n' % N)
